  function aclRule(t,name,type,text){const w=words(text);if(w[0]==='remark')return{remark:w.slice(1).join(' ')};const action=w.shift();if(!['permit','deny'].includes(action))throw new Error('% Expected permit or deny');let protocol='ip';if(type==='extended'){protocol=w.shift();if(!['ip','icmp','tcp','udp'].includes(protocol))throw new Error('% Supported protocols: ip, icmp, tcp, udp');}const address=()=>{const value=w.shift();if(value==='any')return['any','255.255.255.255'];if(value==='host')return[ip(w.shift()),'0.0.0.0'];ip(value);return[value,w.length&&ipv4(w[0])!==null?w.shift():'0.0.0.0'];};const[source,sourceWildcard]=address(),[destination,destinationWildcard]=type==='extended'?address():[null,null];let port;if(w[0]==='eq'){w.shift();const p=w.shift();port={www:80,http:80,https:443,domain:53,ssh:22,telnet:23,ftp:21,tftp:69}[p]||number(p,1,65535);}if(w.length)throw new Error('% Unsupported ACL qualifier. Use ? for supported syntax.');return{action,protocol,source,sourceWildcard,destination,destinationWildcard,port,hits:0};}
